87	// Wrap a state change in a view transition when the platform offers one and
88	// the user has not asked for reduced motion; otherwise apply it directly.
89	export function withScreenTransition(update: () => void, done?: () => void) {
90	  const reduceMotion = window.matchMedia("(prefers-reduced-motion: reduce)").matches;
91	  if (
92	    typeof document.startViewTransition !== "function" ||
93	    reduceMotion ||
94	    document.visibilityState === "hidden" // nothing to animate off-screen
95	  ) {
96	    update();
97	    done?.();
98	    return;
99	  }
100	  const transition = document.startViewTransition(() => {
101	    flushSync(update);
102	  });
103	  // A skipped or aborted transition (hidden tab, rapid re-entry) rejects
104	  // `finished`; that is normal, so swallow it and always run the cleanup.
105	  void transition.finished
106	    .catch(() => {})
107	    .then(() => done?.());
108	}
