217	// A durable breadcrumb that this browser has signed in before. It lets a
218	// returning visitor splash straight toward the app instead of flashing the
219	// landing while Clerk wakes. Reads can fail (private mode); we degrade to "no
220	// hint" rather than throw, so those visitors just meet the landing first.
221	const SESSION_HINT_KEY = "haven:hasSession";
222	
223	function readSessionHint(): boolean {
224	  try {
225	    return window.localStorage.getItem(SESSION_HINT_KEY) !== null;
226	  } catch {
227	    return false;
228	  }
229	}
230	
231	function writeSessionHint(present: boolean): void {
232	  try {
233	    if (present) window.localStorage.setItem(SESSION_HINT_KEY, "1");
234	    else window.localStorage.removeItem(SESSION_HINT_KEY);
235	  } catch {
236	    // Storage blocked -- the returning-visitor fast path simply won't apply.
237	  }
238	}
