13	const PLATFORMS = [
14	  "linkedin",
15	  "x",
16	  "instagram",
17	  "tiktok",
18	  "github",
19	  "facebook",
20	  "threads",
21	  "bluesky",
22	  "other",
23	] as const;
24	
25	// Strict structured-output schema: every property listed in required,
26	// optionality expressed as nullable types, per OpenAI strict mode rules.
27	const EXTRACTION_SCHEMA = {
28	  type: "object",
29	  additionalProperties: false,
30	  required: ["is_profile", "platform", "name", "handle", "headline", "bio"],
31	  properties: {
32	    is_profile: {
33	      type: "boolean",
34	      description:
35	        "True only if the screenshot shows a single person's social or professional profile.",
36	    },
37	    platform: { type: "string", enum: [...PLATFORMS] },
38	    name: {
39	      type: ["string", "null"],
40	      description: "The person's display name as shown.",
41	    },
42	    handle: {
43	      type: ["string", "null"],
44	      description: "The username or @handle if visible, without the URL.",
45	    },
46	    headline: {
47	      type: ["string", "null"],
48	      description: "Their title, tagline, or one-line bio header if visible.",
49	    },
50	    bio: {
51	      type: ["string", "null"],
52	      description: "A short summary of any visible bio or about text.",
53	    },
54	  },
55	} as const;
