57	const EXTRACTION_PROMPT = [
58	  "This is a screenshot the user took of someone's social or professional profile.",
59	  "Identify which platform it is from (branding, layout, UI chrome) and extract",
60	  "the person's visible details. Only report what is actually visible; never",
61	  "guess a handle or invent text. If the image is not a person's profile,",
62	  "set is_profile to false.",
63	].join(" ");
