65	function apiKey(): string {
66	  const key = process.env.OPENAI_API_KEY;
67	  if (key === undefined || key === "") {
68	    throw new Error(
69	      "OPENAI_API_KEY is not set on the Convex deployment. Run: npx convex env set OPENAI_API_KEY <key>",
70	    );
71	  }
72	  return key;
73	}
