95	export async function extractProfile(
96	  imageUrl: string,
97	): Promise<ExtractedProfile> {
98	  const result = (await callOpenAI("chat/completions", {
99	    model: "gpt-4o-mini",
100	    messages: [
101	      {
102	        role: "user",
103	        content: [
104	          { type: "text", text: EXTRACTION_PROMPT },
105	          { type: "image_url", image_url: { url: imageUrl, detail: "high" } },
106	        ],
107	      },
108	    ],
109	    response_format: {
110	      type: "json_schema",
111	      json_schema: {
112	        name: "profile_extraction",
113	        strict: true,
114	        schema: EXTRACTION_SCHEMA,
115	      },
116	    },
117	  })) as {
118	    choices?: Array<{ message?: { content?: string; refusal?: string } }>;
119	  };
120	
121	  const message = result.choices?.[0]?.message;
122	  if (message === undefined || typeof message.content !== "string") {
123	    throw new Error(message?.refusal ?? "OpenAI returned no extraction");
124	  }
125	  const parsed = JSON.parse(message.content) as {
126	    is_profile: boolean;
127	    platform: string;
128	    name: string | null;
129	    handle: string | null;
130	    headline: string | null;
131	    bio: string | null;
132	  };
133	
134	  const name = parsed.name?.trim() ?? "";
135	  if (!parsed.is_profile || name === "") {
136	    throw new Error("Could not read a profile in this screenshot");
137	  }
138	  const clean = (value: string | null): string | undefined => {
139	    const trimmed = value?.trim() ?? "";
140	    return trimmed === "" ? undefined : trimmed;
141	  };
142	  return {
143	    platform: parsed.platform,
144	    name,
145	    handle: clean(parsed.handle),
146	    headline: clean(parsed.headline),
147	    bio: clean(parsed.bio),
148	  };
149	}
