7	// The name is untrusted (anyone can submit any string) and lands inside HTML.
8	// Escape the five characters that would otherwise break out of text content or
9	// an attribute, so a crafted name can never inject markup into the message.
10	function escapeHtml(value: string): string {
11	  return value
12	    .replace(/&/g, "&amp;")
13	    .replace(/</g, "&lt;")
14	    .replace(/>/g, "&gt;")
15	    .replace(/"/g, "&quot;")
