69	export type SendResult =
70	  | { status: "sent"; id: string }
71	  | { status: "skipped"; reason: string }
72	  | { status: "failed"; error: string };
73	
74	// Provider-agnostic entry point. Today it posts to Resend; the whole HTTP shape
75	// lives here so swapping providers touches this one function. Both credentials
76	// are read from the Convex deployment env (like OPENAI_API_KEY): when either is
77	// unset it returns "skipped" rather than throwing, which is the safe no-op that
78	// lets the join flow ship before an email provider is wired up.
79	export async function sendWaitlistConfirmation(args: {
80	  to: string;
81	  name: string;
82	}): Promise<SendResult> {
83	  const apiKey = process.env.RESEND_API_KEY;
84	  const from = process.env.WAITLIST_FROM_EMAIL;
85	  // The only falsy values process.env can hold are undefined and "" -- both
86	  // mean "not configured", so this is the safe no-op gate.
87	  if (!apiKey || !from) {
88	    return {
89	      status: "skipped",
90	      reason: "RESEND_API_KEY or WAITLIST_FROM_EMAIL is not set on the deployment",
91	    };
92	  }
93	
94	  const { subject, html, text } = renderConfirmation(args.name);
95	  const response = await fetch("https://api.resend.com/emails", {
96	    method: "POST",
97	    headers: {
98	      "Content-Type": "application/json",
99	      Authorization: `Bearer ${apiKey}`,
100	    },
101	    body: JSON.stringify({ from, to: args.to, subject, html, text }),
102	  });
103	
104	  if (!response.ok) {
105	    return {
106	      status: "failed",
107	      error: `Resend responded ${response.status}: ${await response.text()}`,
108	    };
109	  }
110	
111	  const data = (await response.json()) as { id?: string };
112	  return { status: "sent", id: data.id ?? "" };
113	}
